```python
def normalize_email(addr):
    """Normalize an address for comparison: strip surrounding whitespace, lowercase everything, and drop a '+tag' suffix from the local part (everything from the first '+'). Exactly one '@' is required, and the local part (after removing the tag) and the domain must be non-empty; otherwise raise ValueError."""
    parts = addr.strip().split("@")
    if len(parts) != 2:
        raise ValueError(f"expected exactly one '@': {addr!r}")
    local, domain = parts
    local = local.split("+", 1)[0].lower()
    domain = domain.lower()
    if not local or not domain:
        raise ValueError(f"empty local part or domain: {addr!r}")
    return f"{local}@{domain}"


if __name__ == "__main__":
    assert normalize_email("Jane.Smith+news@Example.COM") == "jane.smith@example.com"
    assert normalize_email(" jane.smith@example.com ") == "jane.smith@example.com"
    for bad in ["+news@example.com", "a@b@c", "jane", "jane@", "@example.com"]:
        try:
            normalize_email(bad)
        except ValueError:
            pass
        else:
            raise AssertionError(f"accepted {bad!r}")
    print("ok")
```

