from decimal import Decimal, ROUND_HALF_UP


def apply_discount(price_cents, percent):
    """Price in integer cents after a percentage discount, rounded half up to the nearest cent. 0 <= percent <= 100 (int or float) else ValueError. Always returns an int. Percent values like 33.3 must be treated as exactly 33.3, not as a binary float approximation."""
    if not 0 <= percent <= 100:
        raise ValueError("percent must be between 0 and 100")
    exact = Decimal(price_cents) * (100 - Decimal(str(percent))) / 100
    return int(exact.quantize(Decimal(1), rounding=ROUND_HALF_UP))


if __name__ == "__main__":
    assert apply_discount(1005, 10) == 905
    assert apply_discount(1000, 33.3) == 667
    assert apply_discount(100, 0) == 100
    assert apply_discount(100, 100) == 0
    for bad in (-1, 101):
        try:
            apply_discount(100, bad)
        except ValueError:
            pass
        else:
            raise AssertionError(f"expected ValueError for {bad}")
    print("ok")
```

