def _anagram_key(word):
    """Sorted lowercase letters of word; empty if it has no letters."""
    return "".join(sorted(c.lower() for c in word if c.isalpha()))


def anagram_groups(words):
    """Group words that are anagrams of each other. Comparison is case-insensitive and uses letters only (spaces, digits and punctuation are ignored); words with no letters are ignored. Identical strings count once. Return only groups with 2 or more distinct words: each group sorted alphabetically ignoring case (original spelling kept), the groups ordered by their first member (ignoring case)."""
    seen = set()
    groups = {}
    for w in words:
        if w in seen:
            continue
        seen.add(w)
        key = _anagram_key(w)
        if not key:
            continue
        groups.setdefault(key, []).append(w)
    result = [sorted(g, key=str.lower) for g in groups.values() if len(g) > 1]
    result.sort(key=lambda g: g[0].lower())
    return result
```

The bug is in `add()`: it recurses on the right-hand side (`v - add()`), so `10-4-3` parses as `10-(4-3)`. The fix is to loop over `mul()` for the right operand, which makes the operators left associative. Malformed input also needs handling. The tokenizer's `findall` silently skips unknown characters, so `"1 2"` never reaches the trailing-token check. Running past the end of the token list raises `IndexError` instead of `ValueError`, and `"(1+2"` is accepted because the closing paren is never checked. The corrected module below tokenizes strictly, reports any leftover tokens, and raises `ValueError` for all malformed input.

```python
import re

_TOKEN = re.compile(r"([0-9]+|[-+*/()])")


def _tokenize(expr):
    tokens = []
    i = 0
    n = len(expr)
    while True:
        while i < n and expr[i].isspace():
            i += 1
        if i == n:
            break
        m = _TOKEN.match(expr, i)
        if m is None:
            raise ValueError(f"unexpected character {expr[i]!r}")
        tokens.append(m.group(1))
        i = m.end()
    return tokens


def evaluate(expr):
    """Evaluate an arithmetic expression with integers, + - * /, parentheses, unary minus and spaces. Standard precedence (* and / before + and -), all binary operators left associative. '/' is true division (a float). Malformed input (empty, unbalanced parentheses, dangling operator, two numbers in a row, any other character) raises ValueError. Division by zero raises ZeroDivisionError."""
    tokens = _tokenize(expr)
    if not tokens:
        raise ValueError("empty expression")
    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def eat():
        nonlocal pos
        if pos >= len(tokens):
            raise ValueError("unexpected end of expression")
        pos += 1
        return tokens[pos - 1]

    def atom():
        t = eat()
        if t == "(":
            v = add()
            if peek() != ")":
                raise ValueError("unbalanced parentheses")
            eat()
            return v
        if t == "-":
            return -atom()
        if t.isdigit():
            return int(t)
        raise ValueError(f"unexpected token {t!r}")

    def mul():
        v = atom()
        while peek() in ("*", "/"):
            op = eat()
            rhs = atom()
            v = v * rhs if op == "*" else v / rhs
        return v

    def add():
        v = mul()
        while peek() in ("+", "-"):
            op = eat()
            rhs = mul()
            v = v + rhs if op == "+" else v - rhs
        return v

    result = add()
    if pos != len(tokens):
        raise ValueError(f"unexpected trailing token {tokens[pos]!r}")
    return result
```

