        if pos >= len(tokens):
            raise ValueError("unexpected end of expression")
        pos += 1
        return tokens[pos - 1]

    def atom():
        t = eat()
        if t == "(":
            v = add()
            if eat() != ")":
                raise ValueError("expected ')'")
            return v
        if t == "-":
            return -atom()
        if t.isdigit():
            return int(t)
        raise ValueError(f"unexpected token {t!r}")

