            v = v * r if op == "*" else v / r
        return v

    def add():
        v = mul()
        while peek() in ("+", "-"):
            op = eat()
            r = mul()
            v = v + r if op == "+" else v - r
        return v

    if not tokens:
        raise ValueError("empty expression")
    result = add()
    if pos != len(tokens):
        raise ValueError(f"unexpected token {tokens[pos]!r}")
    return result
```

