Bug: `json.dumps` without `sort_keys` keeps insertion order, so `a=1,b=2` and `b=2,a=1` serialize differently. Lists and tuples both become JSON arrays, so they collide. Fix: encode each value into a type-tagged structure with dict keys sorted, then serialize that.

```python
import json


def _encode(value, active):
    """Return a JSON-safe, type-tagged, canonical form of value."""
    if value is None:
        return ["none"]

    t = type(value)  # exact type checks: subclasses (e.g. IntEnum) are rejected

    if t is bool:
        return ["bool", value]
    if t is int:
        return ["int", hex(value)]
    if t is float:
        return ["float", repr(value)]
    if t is str:
        return ["str", value]

    if t is list or t is tuple:
        marker = id(value)
        if marker in active:
            raise TypeError("cache_key does not support cyclic containers")
        active.add(marker)
        try:
            items = [_encode(item, active) for item in value]
        finally:
            active.discard(marker)
        return ["list" if t is list else "tuple", items]

    if t is dict:
        for key in value:
            if type(key) is not str:
                raise TypeError(
                    f"cache_key dict keys must be str, got {type(key).__name__}"
                )
        marker = id(value)
        if marker in active:
            raise TypeError("cache_key does not support cyclic containers")
        active.add(marker)
        try:
            # Keys are unique str, so sorting by key alone is deterministic.
            pairs = [[k, _encode(v, active)] for k, v in sorted(value.items(), key=lambda kv: kv[0])]
        finally:
            active.discard(marker)
        return ["dict", pairs]

    raise TypeError(f"cache_key does not support values of type {t.__name__}")


def cache_key(*args, **kwargs):
    """Stable string key for a call. Equal calls give equal keys: keyword order and nested dict key order do not matter. Values that differ in type give different keys: 1, 1.0 and True are all different, and a list differs from a tuple with the same items. Positional and keyword arguments are distinct (cache_key(1) != cache_key(x=1)). Allowed values: None, bool, int, float, str, and lists, tuples and dicts (with str keys) of those. Anything else, including dicts with non-str keys, raises TypeError."""
    return json.dumps(
        [_encode(args, set()), _encode(kwargs, set())],
        separators=(",", ":"),
    )
```

