```python
import json


def _encode(value, active):
    """Return a canonical, type-tagged, JSON-serializable form of value.

    `active` holds ids of containers currently being encoded, to detect cycles.
    """
    if value is None:
        return ["none"]
    # bool must be checked before int, since bool is a subclass of int.
    if isinstance(value, bool):
        return ["bool", value]
    if isinstance(value, int):
        return ["int", int.__repr__(value)]
    if isinstance(value, float):
        # hex() is exact and distinguishes -0.0, nan and inf deterministically.
        return ["float", float.hex(value)]
    if isinstance(value, str):
        return ["str", str.__str__(value)]
    if isinstance(value, (list, tuple, dict)):
        ident = id(value)
        if ident in active:
            raise TypeError("cannot encode a cyclic container")
        active.add(ident)
        try:
            if isinstance(value, dict):
                for key in value:
                    if not isinstance(key, str):
                        raise TypeError(
                            f"dict keys must be str, got {type(key).__name__}"
                        )
                # Keys are unique str values, so sorting them gives a canonical order.
                return [
                    "dict",
                    [[key, _encode(value[key], active)] for key in sorted(value)],
                ]
            tag = "list" if isinstance(value, list) else "tuple"
            return [tag, [_encode(item, active) for item in value]]
        finally:
            active.discard(ident)
    raise TypeError(f"unsupported type for cache_key: {type(value).__name__}")


def cache_key(*args, **kwargs):
    """Stable string key for a call. Equal calls give equal keys: keyword order and nested dict key order do not matter. Values that differ in type give different keys: 1, 1.0 and True are all different, and a list differs from a tuple with the same items. Positional and keyword arguments are distinct (cache_key(1) != cache_key(x=1)). Allowed values: None, bool, int, float, str, and lists, tuples and dicts (with str keys) of those. Anything else, including dicts with non-str keys, raises TypeError."""
    return json.dumps(
        ["call", _encode(args, set()), _encode(kwargs, set())],
        separators=(",", ":"),
    )
