Bugs: `allow` kept events exactly `window` old (it should drop `e <= t - window`), appended rejected calls before checking the limit, and `retry_after` ignored the limit and could return negative values.

```python
from collections import deque


class RateWindow:
    def __init__(self, limit, window):
        self.limit = limit
        self.window = window
        self.events = deque()

    def _prune(self, t):
        # Event e counts at time t only while e > t - window.
        cutoff = t - self.window
        while self.events and self.events[0] <= cutoff:
            self.events.popleft()

    def allow(self, t):
        self._prune(t)
        if len(self.events) < self.limit:
            self.events.append(t)
            return True
        # Rejected calls do not consume quota.
        return False

    def retry_after(self, t):
        if self.limit <= 0:
            return float("inf")
        cutoff = t - self.window
        active = [e for e in self.events if e > cutoff]
        if len(active) < self.limit:
            return 0
        # Count drops below limit once active[len - limit] expires,
        # i.e. at time e + window.
        e = active[len(active) - self.limit]
        return e + self.window - t
```

