from collections import deque


class RateWindow:
    def __init__(self, limit, window):
        self.limit = limit
        self.window = window
        self.events = deque()

    def _prune(self, t):
        # an event at e counts only while e > t - window
        while self.events and self.events[0] <= t - self.window:
            self.events.popleft()

    def allow(self, t):
        self._prune(t)
        if len(self.events) < self.limit:
            self.events.append(t)
            return True
        return False

    def retry_after(self, t):
        if self.limit <= 0:
            return float("inf")
        live = [e for e in self.events if e > t - self.window]
        if len(live) < self.limit:
            return 0
        # the event at index len(live) - limit must expire before a call is allowed
        return max(0, live[len(live) - self.limit] + self.window - t)
