class Editor:
    def __init__(self, limit=100):
        self.text = ""
        self.limit = limit
        self.undo_stack = []
        self.redo_stack = []

    def insert(self, pos, s):
        pos = min(max(pos, 0), len(self.text))
        self.text = self.text[:pos] + s + self.text[pos:]
        self._record(("ins", pos, s))

    def delete(self, pos, n):
