Bugs: `put` on existing key never bumps count or recency. Eviction ties broken by insertion order, not recency. Zero capacity reaches `min()` on empty dict, raises. Fix: count and recency update on every use, evict by `(freq, last_tick)`, early return when `cap <= 0`.

```python
class LFUCache:
    def __init__(self, capacity):
        self.cap = capacity
        self.data = {}
        self.tick = 0

    def _touch(self, key):
        self.tick += 1
        entry = self.data[key]
        entry[1] += 1
        entry[2] = self.tick

    def get(self, key):
        if key not in self.data:
            return None
        self._touch(key)
        return self.data[key][0]

    def put(self, key, value):
        if self.cap <= 0:
            return
        if key in self.data:
            self.data[key][0] = value
            self._touch(key)
            return
        if len(self.data) >= self.cap:
            victim = min(
                self.data,
                key=lambda k: (self.data[k][1], self.data[k][2]),
            )
            del self.data[victim]
        self.tick += 1
        self.data[key] = [value, 1, self.tick]
