class Bank:
    def __init__(self, balances):
        self.bal = dict(balances)
        self.done = {}

    def transfer(self, src, dst, amount, key=None):
        if key is not None and key in self.done:
            return self.done[key]
        if amount <= 0:
            raise ValueError("amount")
        if src == dst:
            raise ValueError("src == dst")
        if src not in self.bal:
            raise KeyError(src)
        if dst not in self.bal:
            raise KeyError(dst)
        fee = max(1, amount // 100)
        if self.bal[src] < amount + fee:
            ok = False
        else:
            self.bal[src] -= amount + fee
            self.bal[dst] += amount
            ok = True
        if key is not None:
            self.done[key] = ok
        return ok


