class _Subscription:
    __slots__ = ("priority", "handler", "active")

    def __init__(self, priority, handler):
        self.priority = priority
        self.handler = handler
        self.active = True


class Bus:
    def __init__(self):
        self.subs = {}

    def on(self, topic, handler, priority=0):
        sub = _Subscription(priority, handler)
        lst = self.subs.setdefault(topic, [])
        lst.append(sub)
        # Stable sort: higher priority first, equal priorities keep subscription order.
        lst.sort(key=lambda s: -s.priority)

        def unsubscribe():
            # Mark this specific subscription inactive so an in-progress emit skips it.
            sub.active = False
            current = self.subs.get(topic)
            if current is not None:
                # Remove by identity so duplicate handlers are only removed individually.
                # Rebinding (instead of mutating) keeps emit's snapshot safe.
                self.subs[topic] = [s for s in current if s is not sub]

        return unsubscribe

    def emit(self, topic, *args):
        n = 0
        # Snapshot so handlers subscribed during this emit are not called until the next emit.
        for sub in list(self.subs.get(topic, [])):
            # Skip subscriptions unsubscribed earlier in this same emit.
            if not sub.active:
                continue
            sub.handler(*args)
            n += 1
        return n
