The bugs were: the visibility check used `<` instead of `<=`, so a message was redelivered one tick late and a message sent at time 0 couldn't be received at time 0. `ack` and `extend` had no held check, and `receive` had no delivery cap, so poison messages looped forever. The fix below adds a `_held` helper for the held condition and dead-letters any message that is visible again after its third delivery.

```python
class VisQueue:
    MAX_DELIVERIES = 3

    def __init__(self, timeout):
        self.timeout = timeout
        self.items = {}
        self.dead = []
        self.n = 0

    def send(self, payload):
        self.n += 1
        self.items[self.n] = [payload, 0, 0]
        return self.n

    def _held(self, mid, now):
        item = self.items.get(mid)
        if item is None:
            return False
        _, vis, cnt = item
        return cnt > 0 and now < vis

    def receive(self, now):
        for mid in sorted(self.items):
            payload, vis, cnt = self.items[mid]
            if vis <= now:
                if cnt >= self.MAX_DELIVERIES:
                    self.dead.append((mid, payload))
                    del self.items[mid]
                    continue
                self.items[mid] = [payload, now + self.timeout, cnt + 1]
                return mid, payload
        return None

    def ack(self, mid, now):
        if not self._held(mid, now):
            return False
        del self.items[mid]
        return True

    def extend(self, mid, now, extra):
        if not self._held(mid, now):
            return False
        self.items[mid][1] = now + extra
        return True
```

Fixes: visibility check `<` → `<=` (new messages visible at 0, no late redelivery), `ack`/`extend` check the held state and return False for unknown or expired ids, `extend` sets `now + extra` instead of adding to the old deadline, and `receive` moves messages past 3 deliveries to `dead`.

