The loader had four bugs: it split on every underscore instead of `__`, it treated any non-empty string as true for bool defaults, it raised on unknown paths, and it shallow-copied the defaults so nested dicts were shared and mutated. The corrected module below fixes all four.

```python
import copy

_TRUE_STRINGS = frozenset({"1", "true", "yes", "on"})
_FALSE_STRINGS = frozenset({"0", "false", "no", "off"})


def _convert(raw, default):
    """Convert a raw environment string to the type of ``default``."""
    kind = type(default)
    if kind is bool:  # check before int, since bool is a subclass of int
        value = raw.lower()
        if value in _TRUE_STRINGS:
            return True
        if value in _FALSE_STRINGS:
            return False
        raise ValueError(f"invalid boolean value: {raw!r}")
    if kind is int:
        return int(raw)
    if kind is float:
        return float(raw)
    return raw


def _find_parent(cfg, parts):
    """Return the dict holding the leaf named by ``parts[-1]``, or None."""
    node = cfg
    for part in parts[:-1]:
        child = node.get(part)
        if not isinstance(child, dict):
            return None
        node = child
    return node


def load_config(defaults, env, prefix="APP_"):
    cfg = copy.deepcopy(dict(defaults))
    for key, raw in env.items():
        if not key.startswith(prefix):
            continue
        parts = key[len(prefix):].lower().split("__")
        if not all(parts):  # empty segment, e.g. "APP_", "APP_DB__" or "APP_DB____X"
            continue
        parent = _find_parent(cfg, parts)
        if parent is None:
            continue
        leaf = parts[-1]
        if leaf not in parent or isinstance(parent[leaf], dict):
            continue
        parent[leaf] = _convert(raw, parent[leaf])
    return cfg
