Four causes:
- `bool("false")` is `True`, so bool defaults were never parsed.
- Splitting on `_` broke keys that contain underscores. Only `__` separates levels now.
- Unknown paths raised `KeyError`. They're now skipped.
- `dict(defaults)` is shallow, so nested dicts were shared and mutated. `copy.deepcopy` fixes that.

```python
import copy

_TRUE = {"1", "true", "yes", "on"}
_FALSE = {"0", "false", "no", "off"}


def _convert(raw, default):
    # bool must be checked before int, since bool is a subclass of int.
    if isinstance(default, bool):
        v = raw.lower()
        if v in _TRUE:
            return True
        if v in _FALSE:
            return False
        raise ValueError(f"invalid boolean value: {raw!r}")
    if isinstance(default, int):
        return int(raw)
    if isinstance(default, float):
        return float(raw)
    return raw


def _parent(cfg, keys):
    """Return the dict holding the final key, or None if the path does not exist."""
    node = cfg
    for p in keys:
        if not isinstance(node, dict):
            return None
        node = node.get(p)
    return node if isinstance(node, dict) else None


def load_config(defaults, env, prefix="APP_"):
    cfg = copy.deepcopy(defaults)
    for k, raw in env.items():
        if not k.startswith(prefix):
            continue
        path = k[len(prefix):].lower().split("__")
        parent = _parent(cfg, path[:-1])
        if parent is None:
            continue
        leaf = path[-1]
        if leaf not in parent or isinstance(parent[leaf], dict):
            continue
        parent[leaf] = _convert(raw, parent[leaf])
    return cfg
