The module had five bugs: `add` overwrote weights instead of accumulating them, the sort order was wrong for ties, `suggest` sliced to `k-1` results, the prefix wasn't lower-cased, and the `"$"` end marker collided with a literal `$` in words. I fixed each one and replaced the string marker with a private sentinel object so no string key can collide with it.

```python
_END = object()  # private end-of-word marker; never equal to any character key


class Autocomplete:
    def __init__(self):
        self.root = {}
        self.size = 0

    def add(self, word, weight=1):
        node = self.root
        for ch in word.lower():
            node = node.setdefault(ch, {})
        if _END in node:
            node[_END] += weight
        else:
            node[_END] = weight
            self.size += 1

    def remove(self, word):
        node = self.root
        for ch in word.lower():
            if ch not in node:
                return False
            node = node[ch]
        if _END not in node:
            return False
        del node[_END]
        self.size -= 1
        return True

    def suggest(self, prefix, k=5):
        if k <= 0:
            return []
        prefix = prefix.lower()
        node = self.root
        for ch in prefix:
            if ch not in node:
                return []
            node = node[ch]
        found = []

        def walk(n, acc):
            for key, child in n.items():
                if key is _END:
                    # Negate weight so an ascending sort gives
                    # highest weight first, then alphabetical order.
                    found.append((-child, acc))
                else:
                    walk(child, acc + key)

        walk(node, prefix)
        found.sort()
        return [w for _, w in found[:k]]

    def __len__(self):
        return self.size
