import re

_NUM = re.compile(r"\d+\.?\d*|\.\d+")
_OP = re.compile(r"[-+*/^()]")


def _tokenize(s):
    toks = []
    pos = 0
    n = len(s)
    while True:
        while pos < n and s[pos].isspace():
            pos += 1
        if pos == n:
            break
        m = _NUM.match(s, pos) or _OP.match(s, pos)
        if m is None:
            raise ValueError(f"unexpected character {s[pos]!r}")
        toks.append(m.group(0))
        pos = m.end()
    return toks


def evaluate(s):
    toks = _tokenize(s)
    pos = 0

    def peek():
        return toks[pos] if pos < len(toks) else None

    def take():
        nonlocal pos
        t = peek()
        pos += 1
        return t

    def expr():
        v = term()
        while peek() in ("+", "-"):
            op = take()
            r = term()
            v = v + r if op == "+" else v - r
        return v

    def term():
        v = unary()
        while peek() in ("*", "/"):
            op = take()
            r = unary()
            v = v * r if op == "*" else v / r
        return v

    def unary():
        if peek() in ("-", "+"):
            op = take()
            v = unary()
            return -v if op == "-" else v
        return power()

    def power():
        base = atom()
        if peek() == "^":
            take()
            exp = unary()
            result = base ** exp
            if isinstance(result, complex):
                raise ValueError("result is not a real number")
            return result
        return base

    def atom():
        t = take()
        if t is None:
            raise ValueError("unexpected end of expression")
        if t == "(":
            v = expr()
            if take() != ")":
                raise ValueError("unbalanced parentheses")
            return v
        if t[0].isdigit() or t[0] == ".":
            return float(t)
        raise ValueError(f"unexpected token {t!r}")

    result = expr()
    if peek() is not None:
        raise ValueError(f"unexpected token {peek()!r}")
    return result
