The bug is that the tokenizer silently drops anything the regex doesn't match, and the parser doesn't check that it consumed all the tokens. The grammar also has the wrong precedence for unary minus and `^`. The fix rebuilds the tokenizer to reject unknown characters, and rewrites the parser around `factor` (unary) → `power` (right-associative, signed exponent) → `primary`.

```python
import re

_TOKEN = re.compile(r"[0-9]+\.?[0-9]*|\.[0-9]+|[-+*/^()]")


def _tokenize(s):
    toks, i = [], 0
    while i < len(s):
        if s[i].isspace():
            i += 1
            continue
        m = _TOKEN.match(s, i)
        if not m:
            raise ValueError(f"unexpected character {s[i]!r} at {i}")
        toks.append(m.group())
        i = m.end()
    return toks


def evaluate(s):
    toks = _tokenize(s)
    pos = 0

    def peek():
        return toks[pos] if pos < len(toks) else None

    def take():
        nonlocal pos
        t = peek()
        if t is None:
            raise ValueError("unexpected end of expression")
        pos += 1
        return t

    def expr():
        v = term()
        while peek() in ("+", "-"):
            op = take()
            r = term()
            v = v + r if op == "+" else v - r
        return v

    def term():
        v = factor()
        while peek() in ("*", "/"):
            op = take()
            r = factor()
            v = v * r if op == "*" else v / r
        return v

    def factor():
        if peek() in ("+", "-"):
            op = take()
            v = factor()
            return -v if op == "-" else v
        return power()

    def power():
        v = primary()
        if peek() == "^":
            take()
            r = v ** factor()
            if isinstance(r, complex):
                raise ValueError("non-real power result")
            return r
        return v

    def primary():
        t = take()
        if t == "(":
            v = expr()
            if take() != ")":
                raise ValueError("expected ')'")
            return v
        if t[0] not in "0123456789.":
            raise ValueError(f"unexpected {t!r}")
        return float(t)

    v = expr()
    if pos != len(toks):
        raise ValueError(f"unexpected {toks[pos]!r}")
    return v


if __name__ == "__main__":
    cases = {"-2^2": -4, "2^3^2": 512, "-2*3": -6, "2*-3": -6,
             "2^-1": 0.5, "--3": 3, "1+2*3": 7, "(1+2)*3": 9}
    for src, want in cases.items():
        assert evaluate(src) == want, src
    for bad in ["", "2 $ 3", "(2", "2)", "2+", "2 3", "1.2.3", "()"]:
        try:
            evaluate(bad)
        except ValueError:
            continue
        raise AssertionError(f"accepted {bad!r}")
    try:
        evaluate("1/0")
    except ZeroDivisionError:
        pass
    else:
        raise AssertionError("1/0 did not raise")
    print("ok")
```

