```python
def split(total, weights):
    if total < 0:
        raise ValueError("total must be non-negative")
    if any(w < 0 for w in weights):
        raise ValueError("weights must be non-negative")
    W = sum(weights)
    if W == 0:
        raise ValueError("weights must not sum to zero")
    products = [total * w for w in weights]
    shares = [p // W for p in products]
    leftover = total - sum(shares)
    # largest remainder first, ties to lower index; zero weights have remainder 0
    # and can never be among the first `leftover` (remainders sum to leftover*W)
    order = sorted(range(len(weights)), key=lambda i: (-(products[i] % W), i))
    for i in order[:leftover]:
        shares[i] += 1
    return shares


def demo():
    assert split(10, [1, 1, 1]) == [4, 3, 3]
    assert split(100, [1, 2, 3]) == [17, 33, 50]
    assert split(7, [1, 1]) == [4, 3]
    assert split(5, [0, 1]) == [0, 5]
    big = 10**30 + 1
    assert sum(split(big, [1, 1, 1])) == big
    for args in [(-1, [1]), (5, [-1, 2]), (5, [0, 0])]:
        try:
            split(*args)
        except ValueError:
            pass
        else:
            raise AssertionError(f"expected ValueError for {args}")


if __name__ == "__main__":
    demo()
