Fix: expiry boundary `>=`, purge expired before LRU evict, update never evicts, `size` counts live only, `get` hit bumps recency without extending ttl.

```python
from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity, ttl):
        self.cap = capacity
        self.ttl = ttl
        self.d = OrderedDict()

    def get(self, key, now):
        if key not in self.d:
            return None
        v, exp = self.d[key]
        if now >= exp:
            del self.d[key]
            return None
        self.d.move_to_end(key)
        return v

    def put(self, key, value, now):
        if self.cap <= 0:
            return
        if key in self.d:
            self.d[key] = (value, now + self.ttl)
            self.d.move_to_end(key)
            return
        self._purge_expired(now)
        if len(self.d) >= self.cap:
            self.d.popitem(last=False)
        self.d[key] = (value, now + self.ttl)

    def size(self, now):
        return sum(1 for _, exp in self.d.values() if now < exp)

    def _purge_expired(self, now):
        dead = [k for k, (_, exp) in self.d.items() if now >= exp]
        for k in dead:
            del self.d[k]
