The fix covers five issues: expiry now uses `now >= exp`, `get` refreshes recency without extending the TTL, `put` on an existing key updates in place without evicting, expired entries are purged before any live entry is evicted, and `size` counts only live entries.

```python
from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity, ttl):
        self.cap = capacity
        self.ttl = ttl
        self.d = OrderedDict()

    def _purge_expired(self, now):
        dead = [k for k, (_, exp) in self.d.items() if now >= exp]
        for k in dead:
            del self.d[k]

    def get(self, key, now):
        if key not in self.d:
            return None
        v, exp = self.d[key]
        if now >= exp:
            del self.d[key]
            return None
        self.d.move_to_end(key)
        return v

    def put(self, key, value, now):
        if self.cap <= 0:
            return
        exp = now + self.ttl
        if key in self.d:
            self.d[key] = (value, exp)
            self.d.move_to_end(key)
            return
        if len(self.d) >= self.cap:
            self._purge_expired(now)
            while len(self.d) >= self.cap:
                self.d.popitem(last=False)
        self.d[key] = (value, exp)

    def size(self, now):
        return sum(1 for _, exp in self.d.values() if now < exp)
