Fix: replace line-split with a char scanner. Quotes open only at field start. Delimiter and newlines inside quotes stay literal. `""` decodes to `"`. Blank unquoted lines skip. Unterminated quote raises.

```python
def parse_csv(text, delimiter=","):
    if not delimiter:
        raise ValueError("delimiter must be non-empty")
    rows = []
    n = len(text)
    i = 0
    while i < n:
        # Blank line outside quotes: skip
        if text[i] == "\n":
            i += 1
            continue
        if text.startswith("\r\n", i):
            i += 2
            continue

        row = []
        while True:
            buf = []
            # Quoted field: only opens at field start
            if i < n and text[i] == '"':
                i += 1
                while True:
                    if i >= n:
                        raise ValueError("unterminated quoted field")
                    if text[i] == '"':
                        if i + 1 < n and text[i + 1] == '"':
                            buf.append('"')
                            i += 2
                        else:
                            i += 1  # closing quote
                            break
                    else:
                        buf.append(text[i])
                        i += 1
            # Unquoted text (or any chars after a closing quote)
            while (
                i < n
                and not text.startswith(delimiter, i)
                and text[i] != "\n"
                and not text.startswith("\r\n", i)
            ):
                buf.append(text[i])
                i += 1
            row.append("".join(buf))

            if i < n and text.startswith(delimiter, i):
                i += len(delimiter)
                continue  # next field in same row
            # End of row
            if i < n and text[i] == "\n":
                i += 1
            elif text.startswith("\r\n", i):
                i += 2
            break
        rows.append(row)
    return rows
```

