The bug is that `fnmatch` treats `*` as matching across `/`, has no `**` support, and uses different rules for `[...]`. The fix translates the glob into a regular expression with the ticket's rules and fully matches it against the path.

```python
import re
from functools import lru_cache


def _read_char(pattern, j):
    """Read one literal character at index j, honouring backslash escapes."""
    n = len(pattern)
    ch = pattern[j]
    if ch == "\\" and j + 1 < n:
        return pattern[j + 1], j + 2
    return ch, j + 1


def _parse_class(pattern, start):
    """
    Parse a bracket expression beginning at pattern[start] == '['.

    Returns (regex_fragment, next_index), or (None, start) if the class is
    unterminated, in which case the '[' is treated as a literal.
    """
    n = len(pattern)
    j = start + 1
    negate = j < n and pattern[j] == "!"
    if negate:
        j += 1

    parts = []
    first = True
    while True:
        if j >= n:
            return None, start
        ch = pattern[j]
        if ch == "]" and not first:
            j += 1
            break
        first = False

        lo, j = _read_char(pattern, j)
        if j + 1 < n and pattern[j] == "-" and pattern[j + 1] != "]":
            hi, j = _read_char(pattern, j + 1)
            if ord(lo) <= ord(hi):
                parts.append(re.escape(lo) + "-" + re.escape(hi))
            # An inverted range such as [c-a] matches nothing; add nothing.
        else:
            parts.append(re.escape(lo))

    inner = "".join(parts)
    if negate:
        # Negated class: any character outside the set, never "/".
        return "[^" + inner + "/]", j
    if not inner:
        # Positive class with no valid members matches nothing.
        return "(?!)", j
    # Positive class: never "/".
    return "(?!/)[" + inner + "]", j


def _translate(pattern):
    out = []
    n = len(pattern)
    i = 0
    while i < n:
        c = pattern[i]
        if c == "*":
            if pattern.startswith("**/", i):
                # Zero or more whole directories.
                out.append("(?:.*/)?")
                i += 3
            elif pattern.startswith("**", i):
                # Any characters, including "/".
                out.append(".*")
                i += 2
            else:
                # Any run of characters except "/".
                out.append("[^/]*")
                i += 1
        elif c == "?":
            out.append("[^/]")
            i += 1
        elif c == "[":
            frag, nxt = _parse_class(pattern, i)
            if frag is None:
                out.append(re.escape("["))
                i += 1
            else:
                out.append(frag)
                i = nxt
        elif c == "\\":
            lit, nxt = _read_char(pattern, i)
            out.append(re.escape(lit))
            i = nxt
        else:
            out.append(re.escape(c))
            i += 1
    return "".join(out)


@lru_cache(maxsize=1024)
def _compile(pattern):
    return re.compile(_translate(pattern), re.DOTALL)


def glob_match(pattern, path):
    return _compile(pattern).fullmatch(path) is not None
```

