import functools
import re


def _parse_class(p, i):
    n = len(p)
    j = i + 1
    neg = False
    if j < n and p[j] == '!':
        neg = True
        j += 1
    items = []
    first = True
    while j < n:
        c = p[j]
        if c == ']' and not first:
            break
        first = False
        if c == '\\' and j + 1 < n:
            j += 1
            c = p[j]
        j += 1
        if j + 1 < n and p[j] == '-' and p[j + 1] != ']':
            hi = p[j + 1]
            j += 2
            if hi == '\\' and j < n:
                hi = p[j]
                j += 1
            items.append((c, hi))
        else:
            items.append((c, c))
    else:
        return None  # no closing ']': '[' is literal

    body = ''.join(
        re.escape(lo) if lo == hi else re.escape(lo) + '-' + re.escape(hi)
        for lo, hi in items
        if lo <= hi
    )
    if neg:
        return '[^/' + body + ']', j + 1
    if not body:
        return '(?!)', j + 1
    return '(?!/)[' + body + ']', j + 1


@functools.lru_cache(maxsize=None)
def _compile(pattern):
    p = pattern
    n = len(p)
    out = []
    i = 0
    while i < n:
        c = p[i]
        if c == '*':
            if p.startswith('**', i):
                if p.startswith('**/', i):
                    out.append('(?:.*/)?')
                    i += 3
                else:
                    out.append('.*')
                    i += 2
            else:
                out.append('[^/]*')
                i += 1
        elif c == '?':
            out.append('[^/]')
            i += 1
        elif c == '[':
            r = _parse_class(p, i)
            if r is None:
                out.append(re.escape('['))
                i += 1
            else:
                out.append(r[0])
                i = r[1]
        elif c == '\\':
            if i + 1 < n:
                out.append(re.escape(p[i + 1]))
                i += 2
            else:
                out.append(re.escape('\\'))
                i += 1
        else:
            out.append(re.escape(c))
            i += 1
    return re.compile(''.join(out), re.DOTALL)


def glob_match(pattern, path):
    return _compile(pattern).fullmatch(path) is not None
