```python
import re
from functools import lru_cache


def _parse_class(pattern, i):
    """Parse a bracket class starting at pattern[i] == '['.

    Returns (regex, next_index), or None if the class is unclosed
    (then '[' is treated as a literal).
    """
    n = len(pattern)
    j = i + 1
    negate = False
    if j < n and pattern[j] == "!":
        negate = True
        j += 1

    items = []
    first = True
    while True:
        if j >= n:
            return None
        c = pattern[j]
        if c == "]" and not first:
            j += 1
            break
        first = False

        if c == "\\" and j + 1 < n:
            j += 1
            c = pattern[j]
        j += 1

        # Range: c-hi, where '-' is not the last char before ']'
        if j + 1 < n and pattern[j] == "-" and pattern[j + 1] != "]":
            j += 1
            hi = pattern[j]
            j += 1
            if hi == "\\" and j < n:
                hi = pattern[j]
                j += 1
            if c <= hi:
                items.append(re.escape(c) + "-" + re.escape(hi))
        else:
            items.append(re.escape(c))

    if not items:
        # Empty set: positive matches nothing, negated matches any non-"/" char.
        return ("[^/]" if negate else "(?!)"), j

    body = "".join(items)
    # A class never matches "/", so guard every class with a lookahead.
    if negate:
        return "(?!/)[^" + body + "]", j
    return "(?!/)[" + body + "]", j


def _translate(pattern):
    out = []
    i = 0
    n = len(pattern)
    while i < n:
        c = pattern[i]
        if c == "*":
            end = i
            while end < n and pattern[end] == "*":
                end += 1
            run = end - i
            if run >= 2:
                if end < n and pattern[end] == "/":
                    # "**/" : zero or more whole directories
                    out.append("(?:.*/)?")
                    i = end + 1
                else:
                    # "**" : any characters, including "/"
                    out.append(".*")
                    i = end
            else:
                # "*" : any characters except "/"
                out.append("[^/]*")
                i += 1
        elif c == "?":
            out.append("[^/]")
            i += 1
        elif c == "[":
            parsed = _parse_class(pattern, i)
            if parsed is None:
                out.append(re.escape(c))
                i += 1
            else:
                rx, i = parsed
                out.append(rx)
        elif c == "\\":
            if i + 1 < n:
                out.append(re.escape(pattern[i + 1]))
                i += 2
            else:
                out.append(re.escape(c))
                i += 1
        else:
            out.append(re.escape(c))
            i += 1
    return "".join(out)


@lru_cache(maxsize=256)
def _compile(pattern):
    return re.compile(_translate(pattern), re.DOTALL)


def glob_match(pattern, path):
    return _compile(pattern).fullmatch(path) is not None
```

