import copy
import re

_SEGMENT = re.compile(r"([^.\[\]]+)((?:\[[0-9]+\])*)")
_INDEX = re.compile(r"\[([0-9]+)\]")


def _parse(path):
    """Split a path like "a.b[2].c" into ("key", name) and ("index", n) tokens."""
    if not isinstance(path, str):
        raise TypeError("path must be a str")
    if path == "":
        raise ValueError("path must not be empty")
    tokens = []
    for seg in path.split("."):
        m = _SEGMENT.fullmatch(seg)
        if m is None:
            raise ValueError(f"malformed path segment {seg!r}")
        tokens.append(("key", m.group(1)))
        for im in _INDEX.finditer(m.group(2)):
            tokens.append(("index", int(im.group(1))))
    return tokens


def _new_container(kind):
    return {} if kind == "key" else []


def set_path(obj, path, value):
    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")
    tokens = _parse(path)
    # _parse guarantees the first token is a key, but keep the rule explicit.
    if tokens[0][0] != "key":
        raise ValueError("the first step of the path must be a key")

    root = copy.deepcopy(obj)
    node = root
    last = len(tokens) - 1

    for i, (kind, arg) in enumerate(tokens):
        is_last = i == last
        if kind == "key":
            if not isinstance(node, dict):
                raise TypeError(f"key step {arg!r} applied to a non-dict")
            if is_last:
                node[arg] = value
                break
            if arg not in node:
                node[arg] = _new_container(tokens[i + 1][0])
            node = node[arg]
        else:
            if not isinstance(node, list):
                raise TypeError(f"index step [{arg}] applied to a non-list")
            if arg < len(node):
                if is_last:
                    node[arg] = value
                    break
                node = node[arg]
            else:
                # Index is at or beyond the end: pad with None, then place
                # the value (or a new container) at the requested index.
                node.extend([None] * (arg - len(node)))
                if is_last:
                    node.append(value)
                    break
                node.append(_new_container(tokens[i + 1][0]))
                node = node[-1]

    return root
