import copy
import re

_KEY_RE = re.compile(r"[^.\[\]]+")
_IDX_RE = re.compile(r"\[([0-9]+)\]")


def _parse(path):
    if not isinstance(path, str):
        raise TypeError("path must be a str")
    if path == "":
        raise ValueError("empty path")

    steps = []
    n = len(path)

    # First step must be a key.
    m = _KEY_RE.match(path, 0)
    if not m:
        raise ValueError(f"malformed path: {path!r}")
    steps.append(("key", m.group()))
    pos = m.end()

    while pos < n:
        ch = path[pos]
        if ch == "[":
            m = _IDX_RE.match(path, pos)
            if not m:
                raise ValueError(f"malformed index in path: {path!r}")
            steps.append(("index", int(m.group(1))))
            pos = m.end()
        elif ch == ".":
            m = _KEY_RE.match(path, pos + 1)
            if not m:
                raise ValueError(f"malformed key in path: {path!r}")
            steps.append(("key", m.group()))
            pos = m.end()
        else:
            raise ValueError(f"malformed path: {path!r}")
    return steps


def _new_container(next_kind):
    return [] if next_kind == "index" else {}


def set_path(obj, path, value):
    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")

    steps = _parse(path)

    # Work on a deep copy so the caller's structure is never mutated and
    # the result shares no mutable parts with obj.
    root = copy.deepcopy(obj)
    value = copy.deepcopy(value)

    node = root
    last_index = len(steps) - 1
    for i, (kind, key) in enumerate(steps):
        is_last = i == last_index
        next_kind = None if is_last else steps[i + 1][0]

        if kind == "key":
            if not isinstance(node, dict):
                raise TypeError(f"key step {key!r} applied to non-dict")
            if is_last:
                node[key] = value
            else:
                if key not in node:
                    node[key] = _new_container(next_kind)
                node = node[key]
        else:  # index
            if not isinstance(node, list):
                raise TypeError(f"index step [{key}] applied to non-list")
            if key > len(node):
                node.extend([None] * (key - len(node)))
            if is_last:
                if key == len(node):
                    node.append(value)
                else:
                    node[key] = value
            else:
                if key == len(node):
                    node.append(_new_container(next_kind))
                node = node[key]

    return root
```

The bugs were: `take` walked lots in insertion order instead of expiry order, it never checked expiry, it removed stock before discovering a shortfall, and `stock` counted expired lots. `add` also lacked the positive-quantity check. The fix filters out expired and empty lots first, checks total usable stock before removing anything, and sorts by expiry. Python's sort is stable, so equal-expiry lots keep their insertion order.

```python
class Inventory:
    def __init__(self):
        self.lots = {}

    def add(self, sku, qty, expires):
        if qty <= 0:
            raise ValueError("qty must be positive")
        self.lots.setdefault(sku, []).append([expires, qty])

    def _usable(self, sku, today):
        # Drop expired (today > expires) and empty lots for this SKU,
        # then return the remaining lots in insertion order.
        lots = self.lots.get(sku)
        if lots is None:
            return []
        lots[:] = [lot for lot in lots if today <= lot[0] and lot[1] > 0]
        if not lots:
            del self.lots[sku]
            return []
        return lots

    def take(self, sku, qty, today):
        if qty <= 0:
            raise ValueError("qty must be positive")
        usable = self._usable(sku, today)
        if sum(lot[1] for lot in usable) < qty:
            raise ValueError("insufficient")
        taken = []
        # sorted() is stable, so equal expiries keep insertion order.
        for lot in sorted(usable, key=lambda l: l[0]):
            if qty == 0:
                break
            n = min(qty, lot[1])
            lot[1] -= n
            qty -= n
            taken.append((lot[0], n))
        return taken

    def stock(self, sku, today):
        return sum(lot[1] for lot in self._usable(sku, today))
```

Bugs: `take` used insertion order, not expiry. Expired lots were counted and sold. `take` removed stock before checking sufficiency. `add` didn't validate qty. Lot usability was `<` instead of `<=`. Fix: validate first, prune expired, stable sort by expiry, then remove.

```python
class Inventory:
    def __init__(self):
        self.lots = {}

    def add(self, sku, qty, expires):
        if qty <= 0:
            raise ValueError("qty must be positive")
        self.lots.setdefault(sku, []).append([expires, qty])

    def _usable(self, sku, today):
        # Drop expired and empty lots, keep insertion order in storage.
        lots = self.lots.get(sku)
        if lots is None:
            return []
        lots[:] = [lot for lot in lots if today <= lot[0] and lot[1] > 0]
        if not lots:
            del self.lots[sku]
            return []
        # Stable sort: earliest expiry first, insertion order for ties.
        return sorted(lots, key=lambda lot: lot[0])

    def take(self, sku, qty, today):
        if qty <= 0:
            raise ValueError("qty must be positive")
        usable = self._usable(sku, today)
        if sum(lot[1] for lot in usable) < qty:
            raise ValueError("insufficient")
        taken = []
        remaining = qty
        for lot in usable:
            if remaining == 0:
                break
            n = min(remaining, lot[1])
            lot[1] -= n
            remaining -= n
            taken.append((lot[0], n))
        # Remove fully consumed lots from storage.
        if sku in self.lots:
            self.lots[sku][:] = [lot for lot in self.lots[sku] if lot[1] > 0]
            if not self.lots[sku]:
                del self.lots[sku]
        return taken

    def stock(self, sku, today):
        return sum(lot[1] for lot in self._usable(sku, today))
