# ponytail: deep-copies all of obj on every call, copy only the path if big inputs matter

_PATH = re.compile(r"[^.\[\]]+(?:\[[0-9]+\])*(?:\.[^.\[\]]+(?:\[[0-9]+\])*)*")
_STEP = re.compile(r"\[([0-9]+)\]|([^.\[\]]+)")


def _steps(path):
    if not isinstance(path, str) or not _PATH.fullmatch(path):
        raise ValueError(f"malformed path: {path!r}")
    return [("index", int(i)) if i else ("key", k) for i, k in _STEP.findall(path)]


def _new(kind):
    return {} if kind == "key" else []


def set_path(obj, path, value):
    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")
    steps = _steps(path)
    if steps[0][0] != "key":
        raise ValueError("first path step must be a key")

    root = copy.deepcopy(obj)
    value = copy.deepcopy(value)
    node = root
    for i, (kind, key) in enumerate(steps):
        last = i == len(steps) - 1
        nxt = None if last else steps[i + 1][0]
        if kind == "key":
            if not isinstance(node, dict):
                raise TypeError(f"key step {key!r} needs a dict")
            if last:
                node[key] = value
                break
            if key not in node:
                node[key] = _new(nxt)
            node = node[key]
        else:
            if not isinstance(node, list):
                raise TypeError(f"index step [{key}] needs a list")
            if key >= len(node):
                node.extend([None] * (key - len(node)))
                node.append(value if last else _new(nxt))
            elif last:
                node[key] = value
            if last:
                break
            node = node[key]
    return root


