Bug: when full, `push()` overwrites the slot at `head` but never advances `head`, so the oldest item is replaced in place and the buffer still reads from the old start. Fix: when full, write at `head` and advance `head`. I also added the `ValueError` for `capacity < 1` that the docstring promises.

```python
class RingBuffer:
    """Fixed-capacity FIFO queue. push() appends; when full, the oldest item is overwritten. pop() removes and returns the oldest item, raising IndexError when empty. len() is the current item count. items() returns the contents oldest to newest. capacity < 1 raises ValueError."""

    def __init__(self, capacity):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self.buf = [None] * capacity
        self.head = 0
        self.size = 0

    def push(self, x):
        cap = len(self.buf)
        if self.size < cap:
            self.buf[(self.head + self.size) % cap] = x
            self.size += 1
        else:
            # Full: overwrite oldest slot, which becomes newest; next-oldest becomes head.
            self.buf[self.head] = x
            self.head = (self.head + 1) % cap

    def pop(self):
        if self.size == 0:
            raise IndexError("empty")
        x = self.buf[self.head]
        self.buf[self.head] = None
        self.head = (self.head + 1) % len(self.buf)
        self.size -= 1
        return x

    def __len__(self):
        return self.size

    def items(self):
        return [self.buf[(self.head + i) % len(self.buf)] for i in range(self.size)]
```

