    groups = {}
    for w in dict.fromkeys(words):  # dedupe identical strings, keep order
        k = _key(w)
        if k:  # no letters -> ignored
            groups.setdefault(k, []).append(w)
    result = [sorted(g, key=lambda w: (w.lower(), w)) for g in groups.values() if len(g) > 1]
    return sorted(result, key=lambda g: (g[0].lower(), g[0]))


