The bug is that `reserve` subtracts stock one SKU at a time, so a failure partway through leaves earlier SKUs already reduced. It also never checks that quantities are positive, so a negative quantity increases stock. The fix validates the whole order first and only then changes any stock.

```python
class Inventory:
    """Stock levels by SKU. reserve(order) takes a dict sku -> qty and is all-or-nothing: if any SKU is unknown, any qty is not a positive int, or any SKU lacks stock, raise ValueError and change nothing. On success stock is reduced. available(sku) returns the current stock (0 for unknown SKUs). The constructor copies the stock dict it is given."""

    def __init__(self, stock):
        self.stock = dict(stock)

    def available(self, sku):
        return self.stock.get(sku, 0)

    def reserve(self, order):
        # Validate the entire order before modifying anything.
        for sku, qty in order.items():
            if sku not in self.stock:
                raise ValueError(sku)
            if not isinstance(qty, int) or isinstance(qty, bool) or qty <= 0:
                raise ValueError(sku)
            if self.stock[sku] < qty:
                raise ValueError(sku)

        # All checks passed; apply the reservation.
        for sku, qty in order.items():
            self.stock[sku] -= qty
```

The bug is in `add()`: it recurses on the right-hand side (`v - add()`), so `10-4-3` parses as `10-(4-3)`. I changed both `mul()` and `add()` to loop with a left-hand accumulator. I also made the tokenizer reject unknown characters, and added checks for unbalanced parentheses, dangling operators, and trailing input.

```python
import re

_TOKEN_RE = re.compile(r"\s*(?:([0-9]+)|([-+*/()]))")
_TRAIL_RE = re.compile(r"\s*")


def _tokenize(expr):
    tokens = []
    pos = 0
    while True:
        m = _TOKEN_RE.match(expr, pos)
        if m is None:
            break
        tokens.append(m.group(1) if m.group(1) is not None else m.group(2))
        pos = m.end()
    if _TRAIL_RE.fullmatch(expr, pos) is None:
        raise ValueError(f"invalid character in expression at position {pos}")
    return tokens


def evaluate(expr):
    """Evaluate an arithmetic expression with integers, + - * /, parentheses, unary minus and spaces. Standard precedence (* and / before + and -), all binary operators left associative. '/' is true division (a float). Malformed input (empty, unbalanced parentheses, dangling operator, two numbers in a row, any other character) raises ValueError. Division by zero raises ZeroDivisionError."""
    tokens = _tokenize(expr)
    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def eat():
        nonlocal pos
        if pos >= len(tokens):
            raise ValueError("unexpected end of expression")
        pos += 1
        return tokens[pos - 1]

    def atom():
        t = eat()
        if t == "(":
            v = add()
            if eat() != ")":
                raise ValueError("expected ')'")
            return v
        if t == "-":
            return -atom()
        if t.isdigit():
            return int(t)
        raise ValueError(f"unexpected token {t!r}")

    def mul():
        v = atom()
        while peek() in ("*", "/"):
            op = eat()
            rhs = atom()
            v = v * rhs if op == "*" else v / rhs
        return v

    def add():
        v = mul()
        while peek() in ("+", "-"):
            op = eat()
            rhs = mul()
            v = v + rhs if op == "+" else v - rhs
        return v

    result = add()
    if pos != len(tokens):
        raise ValueError(f"unexpected token {tokens[pos]!r}")
    return result
```

