        raise ValueError("empty expression")
    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def eat():
        nonlocal pos
        if pos >= len(tokens):
            raise ValueError("unexpected end of expression")
        pos += 1
        return tokens[pos - 1]

    def atom():
        t = eat()
        if t == "(":
            v = add()
            if eat() != ")":
                raise ValueError("expected ')'")
            return v
        if t == "-":
            return -atom()
        if t.isdigit():
            return int(t)
        raise ValueError(f"unexpected token {t!r}")

    def mul():
        v = atom()
        while peek() in ("*", "/"):
            op = eat()
            rhs = atom()
            v = v * rhs if op == "*" else v / rhs
        return v

    def add():
        v = mul()
        while peek() in ("+", "-"):
            op = eat()
            rhs = mul()
            v = v + rhs if op == "+" else v - rhs
        return v

    result = add()
    if pos != len(tokens):
        raise ValueError(f"unexpected token {tokens[pos]!r}")
    return result
