    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def eat():
        nonlocal pos
        if pos >= len(tokens):
            raise ValueError("unexpected end of expression")
        pos += 1
        return tokens[pos - 1]

    def primary():
        t = eat()
        if t == "(":
            v = add()
            if eat() != ")":
                raise ValueError("expected ')'")
            return v
        if t.isdigit():
            return int(t)
        raise ValueError(f"unexpected token {t!r}")

    def unary():
        if peek() == "-":
            eat()
            return -unary()
        return primary()

    def mul():
        v = unary()
        while peek() in ("*", "/"):
            op = eat()
            rhs = unary()
            v = v * rhs if op == "*" else v / rhs
        return v

    def add():
        v = mul()
        while peek() in ("+", "-"):
            op = eat()
            rhs = mul()
            v = v + rhs if op == "+" else v - rhs
        return v

    result = add()
    if pos != len(tokens):
        raise ValueError(f"unexpected trailing token {tokens[pos]!r}")
    return result
