import re

_TOKEN = re.compile(r"[0-9]+|[-+*/()]")


def _tokenize(expr):
    tokens, i = [], 0
    while i < len(expr):
        if expr[i].isspace():
            i += 1
            continue
        m = _TOKEN.match(expr, i)
        if not m:
            raise ValueError(f"unexpected character {expr[i]!r}")
        tokens.append(m.group())
        i = m.end()
    return tokens


def evaluate(expr):
    """Evaluate an arithmetic expression with integers, + - * /, parentheses, unary minus and spaces. Standard precedence (* and / before + and -), all binary operators left associative. '/' is true division (a float). Malformed input (empty, unbalanced parentheses, dangling operator, two numbers in a row, any other character) raises ValueError. Division by zero raises ZeroDivisionError."""
    tokens = _tokenize(expr)
    if not tokens:
        raise ValueError("empty expression")
    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def eat():
        nonlocal pos
        if pos >= len(tokens):
            raise ValueError("unexpected end of expression")
        pos += 1
        return tokens[pos - 1]

    def atom():
        t = eat()
        if t == "(":
            v = add()
            if eat() != ")":
                raise ValueError("expected ')'")
            return v
        if t == "-":
            return -atom()
        if t.isdigit():
            return int(t)
        raise ValueError(f"unexpected token {t!r}")

    def mul():
        v = atom()
        while peek() in ("*", "/"):
            op = eat()
            r = atom()
            v = v * r if op == "*" else v / r
        return v

    def add():
        v = mul()
        while peek() in ("+", "-"):
            op = eat()
            r = mul()
            v = v + r if op == "+" else v - r
        return v

    v = add()
    if pos != len(tokens):
        raise ValueError(f"unexpected token {tokens[pos]!r}")
    return v


if __name__ == "__main__":
    assert evaluate("10-4-3") == 3
    assert evaluate("2*-3") == -6
    assert evaluate("6/3") == 2.0
    assert evaluate(" (1 + 2) * 3 ") == 9
    for bad in ["", "1 2", "(1+2", "1+", "()", "1 & 2"]:
        try:
            evaluate(bad)
        except ValueError:
            pass
        else:
            raise AssertionError(f"accepted {bad!r}")
    print("ok")
```

