The bug is that `json.dumps([args, kwargs])` keeps keyword order, lets `json` map lists and tuples to the same array, and doesn't tag scalar types. The fix encodes each value as an explicitly tagged structure, sorts dict keys, and rejects unsupported types.

```python
import json


def _encode(value, active):
    """Return a canonical, type-tagged, JSON-safe representation of value."""
    t = type(value)
    if value is None:
        return ["none"]
    if t is bool:
        return ["bool", "true" if value else "false"]
    if t is int:
        return ["int", str(value)]
    if t is float:
        # repr keeps -0.0 distinct from 0.0 and gives a stable text form for nan/inf.
        return ["float", repr(value)]
    if t is str:
        return ["str", value]
    if t is list or t is tuple:
        marker = id(value)
        if marker in active:
            raise TypeError("cyclic structures are not supported")
        active.add(marker)
        try:
            items = [_encode(item, active) for item in value]
        finally:
            active.discard(marker)
        return ["list" if t is list else "tuple", items]
    if t is dict:
        for k in value:
            if type(k) is not str:
                raise TypeError(
                    f"dict keys must be str, not {type(k).__qualname__}"
                )
        marker = id(value)
        if marker in active:
            raise TypeError("cyclic structures are not supported")
        active.add(marker)
        try:
            pairs = [[k, _encode(v, active)] for k, v in value.items()]
        finally:
            active.discard(marker)
        # Keys are unique str values, so sorting by key gives a canonical order.
        pairs.sort(key=lambda pair: pair[0])
        return ["dict", pairs]
    raise TypeError(f"unsupported type: {t.__qualname__}")


def cache_key(*args, **kwargs):
    """Stable string key for a call. Equal calls give equal keys: keyword order and nested dict key order do not matter. Values that differ in type give different keys: 1, 1.0 and True are all different, and a list differs from a tuple with the same items. Positional and keyword arguments are distinct (cache_key(1) != cache_key(x=1)). Allowed values: None, bool, int, float, str, and lists, tuples and dicts (with str keys) of those. Anything else, including dicts with non-str keys, raises TypeError."""
    payload = [
        "call",
        _encode(args, set()),
        _encode(kwargs, set()),
    ]
    return json.dumps(payload, separators=(",", ":"), ensure_ascii=True)
```

Notes on behaviour:
- Type checks are exact (`type(x) is int`), so subclasses such as `IntEnum` or namedtuples raise `TypeError` instead of silently sharing a key with their base type. This follows the docstring's "anything else raises TypeError" rule.
- `0.0` and `-0.0` produce different keys because `repr` distinguishes them. Equal floats that differ only in sign are therefore not treated as the same key. This is a conservative choice to avoid false hits; say if you want them merged.
- Cyclic containers raise `TypeError` rather than recursing forever.

```python
import json


def _enc(v):
    t = type(v)
    if v is None:
        return ["N"]
    if t is bool:
        return ["B", v]
    if t is int:
        return ["I", str(v)]
    if t is float:
        return ["F", repr(v)]
    if t is str:
        return ["S", v]
    if t is list:
        return ["L", [_enc(x) for x in v]]
    if t is tuple:
        return ["T", [_enc(x) for x in v]]
    if t is dict:
        items = []
        for k, x in v.items():
            if type(k) is not str:
                raise TypeError(f"dict keys must be str, not {type(k).__name__}")
            items.append([k, _enc(x)])
        items.sort(key=lambda kv: kv[0])
        return ["D", items]
    raise TypeError(f"unsupported type: {t.__name__}")


def cache_key(*args, **kwargs):
    """Stable string key for a call. Equal calls give equal keys: keyword order and nested dict key order do not matter. Values that differ in type give different keys: 1, 1.0 and True are all different, and a list differs from a tuple with the same items. Positional and keyword arguments are distinct (cache_key(1) != cache_key(x=1)). Allowed values: None, bool, int, float, str, and lists, tuples and dicts (with str keys) of those. Anything else, including dicts with non-str keys, raises TypeError."""
    pos = ["A", [_enc(a) for a in args]]
    kw = ["K", [[k, _enc(v)] for k, v in sorted(kwargs.items(), key=lambda kv: kv[0])]]
    return json.dumps([pos, kw])
