Bug: `json.dumps` keeps kwarg and dict key order, and it writes `1`, `1.0`, `True` and lists/tuples all the same way. Fix: type-tagged recursive encoding with sorted dict keys. Each value self-delimits, so keys can't collide.

```python
import json


def _enc(v, stack):
    t = type(v)
    if v is None:
        return "N"
    if t is bool:
        return "T" if v else "F"
    if t is int:
        return "i" + format(v, "x")
    if t is float:
        return "f" + repr(v)
    if t is str:
        return "s" + json.dumps(v)
    if t is list or t is tuple:
        marker = id(v)
        if marker in stack:
            raise ValueError("cyclic value")
        stack.add(marker)
        try:
            body = ",".join(_enc(item, stack) for item in v)
        finally:
            stack.discard(marker)
        return ("l[" if t is list else "t[") + body + "]"
    if t is dict:
        for key in v:
            if type(key) is not str:
                raise TypeError(f"dict keys must be str, got {type(key).__name__}")
        marker = id(v)
        if marker in stack:
            raise ValueError("cyclic value")
        stack.add(marker)
        try:
            body = ",".join(
                _enc(key, stack) + ":" + _enc(v[key], stack) for key in sorted(v)
            )
        finally:
            stack.discard(marker)
        return "d{" + body + "}"
    raise TypeError(f"unsupported type: {t.__name__}")


def cache_key(*args, **kwargs):
    """Stable string key for a call. Equal calls give equal keys: keyword order and nested dict key order do not matter. Values that differ in type give different keys: 1, 1.0 and True are all different, and a list differs from a tuple with the same items. Positional and keyword arguments are distinct (cache_key(1) != cache_key(x=1)). Allowed values: None, bool, int, float, str, and lists, tuples and dicts (with str keys) of those. Anything else, including dicts with non-str keys, raises TypeError."""
    stack = set()
    return _enc(args, stack) + _enc(kwargs, stack)
```

