```python
import json

_TAGS = {bool: "b", int: "i", float: "f", str: "s"}


def _enc(v):
    if v is None:
        return None
    t = type(v)
    if t in _TAGS:
        return [_TAGS[t], v]
    if t is list:
        return ["l", [_enc(x) for x in v]]
    if t is tuple:
        return ["t", [_enc(x) for x in v]]
    if t is dict:
        if not all(type(k) is str for k in v):
            raise TypeError("dict keys must be str")
        return ["d", [[k, _enc(v[k])] for k in sorted(v)]]
    raise TypeError(f"unsupported type: {t.__name__}")


def cache_key(*args, **kwargs):
    """Stable string key for a call. Equal calls give equal keys: keyword order and nested dict key order do not matter. Values that differ in type give different keys: 1, 1.0 and True are all different, and a list differs from a tuple with the same items. Positional and keyword arguments are distinct (cache_key(1) != cache_key(x=1)). Allowed values: None, bool, int, float, str, and lists, tuples and dicts (with str keys) of those. Anything else, including dicts with non-str keys, raises TypeError."""
    # ponytail: recursive tagged encoding, no cycle detection; a cyclic arg raises RecursionError
    return json.dumps([_enc(args), _enc(kwargs)])


if __name__ == "__main__":
    assert cache_key(a=1, b=2) == cache_key(b=2, a=1)
    assert cache_key({"x": {"p": 1, "q": 2}}) == cache_key({"x": {"q": 2, "p": 1}})
    assert cache_key([1, 2]) != cache_key((1, 2))
    assert cache_key(1) != cache_key(1.0) != cache_key(True)
    assert cache_key(1) != cache_key(x=1)
    assert cache_key(None) != cache_key(0)
    for bad in ({1: "x"}, {"a": object()}, {2, 3}):
        try:
            cache_key(bad)
        except TypeError:
            pass
        else:
            raise AssertionError(f"expected TypeError for {bad!r}")
    print("ok")
