Bugs: `allow` records rejected calls, so they eat quota. Pruning uses `<` where the ticket needs `<=`, which keeps boundary events alive. `retry_after` ignores the limit and can go negative.

```python
from collections import deque


class RateWindow:
    def __init__(self, limit, window):
        self.limit = limit
        self.window = window
        self.events = deque()

    def _expire(self, t):
        # Event e counts only while e > t - window, so drop e <= t - window.
        while self.events and self.events[0] <= t - self.window:
            self.events.popleft()

    def allow(self, t):
        self._expire(t)
        if len(self.events) < self.limit:
            self.events.append(t)
            return True
        return False

    def retry_after(self, t):
        if self.limit <= 0:
            return float("inf")
        live = [e for e in self.events if e > t - self.window]
        if len(live) < self.limit:
            return 0
        # Must expire the oldest (len(live) - limit + 1) live events;
        # the last of those is live[len(live) - limit].
        return live[len(live) - self.limit] + self.window - t
```

