from collections import deque


class RateWindow:
    def __init__(self, limit, window):
        self.limit = limit
        self.window = window
        self.events = deque()

    def _evict(self, t):
        # Drop events with e <= t - window (no longer counted).
        while self.events and self.events[0] <= t - self.window:
            self.events.popleft()

    def allow(self, t):
        self._evict(t)
        if len(self.events) < self.limit:
            self.events.append(t)
            return True
        return False

    def retry_after(self, t):
        if self.limit <= 0:
            return float("inf")
        live = [e for e in self.events if e > t - self.window]
        if len(live) < self.limit:
            return 0
        # Wait until the event that brings the count below limit expires.
        return max(0, live[len(live) - self.limit] + self.window - t)
