Fixed: priority sorts descending, unsubscribe is per-subscription and idempotent, and `emit` iterates a snapshot that skips deactivated entries.

```python
class _Sub:
    __slots__ = ("priority", "handler", "active")

    def __init__(self, priority, handler):
        self.priority = priority
        self.handler = handler
        self.active = True


class Bus:
    def __init__(self):
        self.subs = {}

    def on(self, topic, handler, priority=0):
        sub = _Sub(priority, handler)
        lst = self.subs.setdefault(topic, [])
        lst.append(sub)
        # stable sort: higher priority first, equal priority keeps subscription order
        lst.sort(key=lambda s: -s.priority)

        def unsubscribe():
            if not sub.active:
                return
            sub.active = False
            lst.remove(sub)  # identity-based: removes only this subscription

        return unsubscribe

    def emit(self, topic, *args):
        n = 0
        # snapshot: handlers subscribed during emit are not called until next emit
        for sub in list(self.subs.get(topic, [])):
            # skip handlers unsubscribed earlier in this emit
            if not sub.active:
                continue
            sub.handler(*args)
            n += 1
        return n
