Bugs: visibility check used `<` (off by one tick), `ack` ignored hold state and crashed or deleted on unknown/expired ids, `extend` added to old deadline instead of setting `now + extra`, and no delivery cap so poison messages looped forever.

```python
class VisQueue:
    MAX_DELIVERIES = 3

    def __init__(self, timeout):
        self.timeout = timeout
        self.items = {}
        self.dead = []
        self.n = 0

    def _held(self, mid, now):
        entry = self.items.get(mid)
        if entry is None:
            return False
        _, vis, cnt = entry
        return cnt > 0 and now < vis

    def send(self, payload):
        self.n += 1
        self.items[self.n] = [payload, 0, 0]
        return self.n

    def receive(self, now):
        for mid in sorted(self.items):
            payload, vis, cnt = self.items[mid]
            if vis <= now:
                if cnt >= self.MAX_DELIVERIES:
                    del self.items[mid]
                    self.dead.append((mid, payload))
                    continue
                self.items[mid] = [payload, now + self.timeout, cnt + 1]
                return mid, payload
        return None

    def ack(self, mid, now):
        if not self._held(mid, now):
            return False
        del self.items[mid]
        return True

    def extend(self, mid, now, extra):
        if not self._held(mid, now):
            return False
        self.items[mid][1] = now + extra
        return True
