def _wrap_words(words, width):
    lines = []
    line = ""
    for w in words:
        if len(w) > width:
            # A word too long for any line is cut into full-width pieces.
            # The current line must be flushed first, since a full piece
            # cannot share a line with earlier text.
            if line:
                lines.append(line)
                line = ""
            while len(w) > width:
                lines.append(w[:width])
                w = w[width:]
            # The remainder (1..width chars) starts a line that later words may continue.
            line = w
        elif not line:
            line = w
        elif len(line) + 1 + len(w) <= width:
            line += " " + w
        else:
            lines.append(line)
            line = w
    if line:
        lines.append(line)
    return lines


def wrap(text, width):
    if width < 1:
        raise ValueError("width must be >= 1")

    # Group consecutive non-blank lines into paragraphs. Blank lines
    # (empty or whitespace-only) separate paragraphs.
    paragraphs = []
    current = []
    for raw in text.splitlines():
        if raw.strip():
            current.append(raw)
        elif current:
            paragraphs.append(current)
            current = []
    if current:
        paragraphs.append(current)

    result = []
    for i, para in enumerate(paragraphs):
        if i:
            result.append("")
        result.extend(_wrap_words(" ".join(para).split(), width))
    return result
