The bug comes from four separate problems in the loader:

- **Boolean parsing:** `type(default)(raw)` calls `bool("false")`, which is `True`.
- **Underscores in keys:** splitting on every `_` breaks keys like `max_conns`. The separator is now `__`.
- **Unknown variables:** missing paths raised `KeyError`. They are now ignored.
- **Mutated defaults:** `dict(defaults)` is shallow, so nested dicts were shared and modified. The loader now deep-copies the defaults.

I also ignore overrides whose target is a section (a dict) rather than a leaf value, since a string cannot replace a section.

```python
import copy

_TRUE = {"1", "true", "yes", "on"}
_FALSE = {"0", "false", "no", "off"}


def _convert(raw, default):
    # bool must be checked before int, because bool is a subclass of int.
    if isinstance(default, bool):
        value = raw.lower()
        if value in _TRUE:
            return True
        if value in _FALSE:
            return False
        raise ValueError(f"invalid boolean value: {raw!r}")
    if isinstance(default, int):
        return int(raw)
    if isinstance(default, float):
        return float(raw)
    return raw


def load_config(defaults, env, prefix="APP_"):
    cfg = copy.deepcopy(defaults)
    for k, raw in env.items():
        if not k.startswith(prefix):
            continue
        # A double underscore separates nesting levels; a single underscore
        # is part of the key name.
        path = k[len(prefix):].lower().split("__")

        node = cfg
        found = True
        for p in path[:-1]:
            if not isinstance(node, dict) or not isinstance(node.get(p), dict):
                found = False
                break
            node = node[p]
        if not found or not isinstance(node, dict) or path[-1] not in node:
            continue  # unknown path: ignore
        if isinstance(node[path[-1]], dict):
            continue  # refers to a section, not a leaf value: ignore
        node[path[-1]] = _convert(raw, node[path[-1]])
    return cfg
```

Bugs: `split("_")` breaks keys with underscores, `type(x)(raw)` makes `"false"` truthy, missing paths raise `KeyError`, and `dict(defaults)` is shallow so nested dicts get mutated. Fix: split on `__`, parse bools explicitly, skip unknown paths, deep-copy defaults.

```python
import copy

_TRUE = {"1", "true", "yes", "on"}
_FALSE = {"0", "false", "no", "off"}


def _convert(default, raw):
    # bool before int: bool is a subclass of int
    if isinstance(default, bool):
        low = raw.lower()
        if low in _TRUE:
            return True
        if low in _FALSE:
            return False
        raise ValueError(f"invalid boolean value: {raw!r}")
    if isinstance(default, int):
        return int(raw)
    if isinstance(default, float):
        return float(raw)
    return raw


def _locate(cfg, path):
    """Return (parent_dict, leaf_key) if path exists in cfg, else None."""
    node = cfg
    for p in path[:-1]:
        if not isinstance(node, dict) or p not in node:
            return None
        node = node[p]
    if not isinstance(node, dict) or path[-1] not in node:
        return None
    return node, path[-1]


def load_config(defaults, env, prefix="APP_"):
    cfg = copy.deepcopy(defaults)
    for k, raw in env.items():
        if not k.startswith(prefix):
            continue
        path = k[len(prefix):].lower().split("__")
        loc = _locate(cfg, path)
        if loc is None:
            continue
        node, key = loc
        node[key] = _convert(node[key], raw)
    return cfg
