Bugs: `findall` silently drops bad chars. No check for leftover tokens or unmatched `(`. `atom` accepts any token as float. `^` loops left-assoc. Unary minus binds inside `^`, so `-2^2` gives 4.

```python
import re

_TOKEN = re.compile(r"\s*(?:(\d+\.?\d*|\.\d+)|([-+*/^()]))")


def _tokenize(s):
    toks = []
    pos = 0
    while True:
        m = _TOKEN.match(s, pos)
        if m is None:
            rest = s[pos:]
            if rest.strip() == "":
                break
            raise ValueError(f"unexpected character {rest.lstrip()[0]!r}")
        toks.append(m.group(1) if m.group(1) is not None else m.group(2))
        pos = m.end()
    return toks


def _pow(base, exp):
    r = base ** exp
    if isinstance(r, complex):
        raise ValueError("complex result not supported")
    return r


def evaluate(s):
    toks = _tokenize(s)
    pos = 0

    def peek():
        return toks[pos] if pos < len(toks) else None

    def take():
        nonlocal pos
        t = peek()
        if t is None:
            raise ValueError("unexpected end of expression")
        pos += 1
        return t

    def expr():
        v = term()
        while peek() in ("+", "-"):
            op = take()
            r = term()
            v = v + r if op == "+" else v - r
        return v

    def term():
        v = unary()
        while peek() in ("*", "/"):
            op = take()
            r = unary()
            v = v * r if op == "*" else v / r
        return v

    def unary():
        t = peek()
        if t in ("-", "+"):
            take()
            v = unary()
            return -v if t == "-" else v
        return power()

    def power():
        base = atom()
        if peek() == "^":
            take()
            exp = unary()  # right-assoc; exponent may carry a sign
            return _pow(base, exp)
        return base

    def atom():
        t = take()
        if t == "(":
            v = expr()
            if take() != ")":
                raise ValueError("expected ')'")
            return v
        if t[0].isdigit() or t[0] == ".":
            return float(t)
        raise ValueError(f"unexpected token {t!r}")

    result = expr()
    if pos != len(toks):
        raise ValueError(f"unexpected token {toks[pos]!r}")
    return result
```

The module has five bugs, and they have separate causes:

- **Re-adding resets weight:** `add` assigns `node["$"] = weight`; it should accumulate.
- **Reverse alphabetical order for ties:** `sort(reverse=True)` flips the word order as well as the weight order.
- **`k-1` results:** the slice `found[:k - 1]` drops one result. `k <= 0` also needs an explicit guard, since a negative slice would return the wrong items.
- **Upper-case prefixes find nothing:** `suggest` never lower-cases the prefix.
- **`$` mixing:** the end-of-word marker `"$"` is also a valid character key, so a word containing `$` collides with the marker. A private sentinel object cannot collide with any string key.

```python
_END = object()  # end-of-word marker; cannot collide with any character key


class Autocomplete:
    def __init__(self):
        self.root = {}
        self.size = 0

    def add(self, word, weight=1):
        node = self.root
        for ch in word.lower():
            node = node.setdefault(ch, {})
        if _END not in node:
            self.size += 1
            node[_END] = weight
        else:
            node[_END] += weight

    def remove(self, word):
        node = self.root
        for ch in word.lower():
            if ch not in node:
                return False
            node = node[ch]
        if _END not in node:
            return False
        del node[_END]
        self.size -= 1
        return True

    def suggest(self, prefix, k=5):
        if k <= 0:
            return []
        prefix = prefix.lower()
        node = self.root
        for ch in prefix:
            if ch not in node:
                return []
            node = node[ch]
        found = []

        def walk(n, acc):
            for key, child in n.items():
                if key is _END:
                    found.append((child, acc))
                else:
                    walk(child, acc + key)

        walk(node, prefix)
        found.sort(key=lambda item: (-item[0], item[1]))
        return [w for _, w in found[:k]]

    def __len__(self):
        return self.size
