import re

_NUMBER = re.compile(r"[0-9]+\.?[0-9]*|\.[0-9]+")
_OPS = "+-*/^()"


def _tokenize(s):
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c.isspace():
            i += 1
            continue
        m = _NUMBER.match(s, i)
        if m:
            tokens.append(("num", float(m.group())))
            i = m.end()
        elif c in _OPS:
            tokens.append(("op", c))
            i += 1
        else:
            raise ValueError(f"unexpected character {c!r} at position {i}")
    return tokens


def evaluate(s):
    toks = _tokenize(s)
    pos = 0

    def peek_op(*ops):
        if pos < len(toks) and toks[pos][0] == "op" and toks[pos][1] in ops:
            return toks[pos][1]
        return None

    def take():
        nonlocal pos
        if pos >= len(toks):
            raise ValueError("unexpected end of input")
        tok = toks[pos]
        pos += 1
        return tok

    def expr():
        v = term()
        while True:
            op = peek_op("+", "-")
            if op is None:
                return v
            take()
            r = term()
            v = v + r if op == "+" else v - r

    def term():
        v = unary()
        while True:
            op = peek_op("*", "/")
            if op is None:
                return v
            take()
            r = unary()
            v = v * r if op == "*" else v / r

    def unary():
        op = peek_op("+", "-")
        if op is not None:
            take()
            v = unary()
            return -v if op == "-" else v
        return power()

    def power():
        base = atom()
        if peek_op("^") is not None:
            take()
            r = base ** unary()
            if isinstance(r, complex):
                raise ValueError("result is not a real number")
            return r
        return base

    def atom():
        tok = take()
        if tok[0] == "num":
            return tok[1]
        if tok[1] == "(":
            v = expr()
            if take() != ("op", ")"):
                raise ValueError("expected ')'")
            return v
        raise ValueError(f"unexpected token {tok[1]!r}")

    v = expr()
    if pos != len(toks):
        raise ValueError(f"unexpected token {toks[pos][1]!r}")
    return v
