    toks, i = [], 0
    while True:
        m = _TOKEN.match(s, i)
        if m is None:
            rest = s[i:].lstrip()
            if rest:
                raise ValueError(f"unexpected character {rest[0]!r}")
            return toks
        toks.append(m.group(1))
        i = m.end()


def evaluate(s):
    toks = _tokenize(s)
    pos = 0

    def peek():
        return toks[pos] if pos < len(toks) else None

    def take():
        nonlocal pos
        t = peek()
        pos += 1
        return t

    def expr():
        v = term()
        while peek() in ("+", "-"):
            op = take()
            r = term()
            v = v + r if op == "+" else v - r
        return v

    def term():
        v = unary()
        while peek() in ("*", "/"):
            op = take()
            r = unary()
            v = v * r if op == "*" else v / r
        return v

    def unary():
        if peek() in ("+", "-"):
            op = take()
            v = unary()
            return -v if op == "-" else v
        return power()

    def power():
        v = primary()
        if peek() == "^":
            take()
            v = v ** unary()  # right-assoc via unary -> power recursion
            if isinstance(v, complex):
