    shares = [total * w // W for w in weights]
    left = total - sum(shares)
    # largest remainder first, ties to lower index; zero weights have remainder 0 and never win a cent
    order = sorted(range(len(weights)), key=lambda i: (-(total * weights[i] % W), i))
    for i in order[:left]:
        shares[i] += 1
    return shares


