Bug: `fnmatch` treats `*` as crossing `/`, has no `**`, and has different class rules. Fix: translate the glob to a regex that enforces the ticket's rules, then `re.fullmatch`.

```python
import re


def _parse_class(pattern, start):
    """Parse a bracket expression starting at pattern[start] == '['.

    Returns (regex, next_index), or None if the class is unclosed.
    Classes never match '/'.
    """
    n = len(pattern)
    j = start + 1
    negate = j < n and pattern[j] == '!'
    if negate:
        j += 1

    items = []
    first = True
    while True:
        if j >= n:
            return None
        c = pattern[j]
        if c == ']' and not first:
            j += 1
            break
        first = False
        if c == '\\' and j + 1 < n:
            j += 1
            c = pattern[j]
        j += 1

        if j + 1 < n and pattern[j] == '-' and pattern[j + 1] != ']':
            hi = pattern[j + 1]
            j += 2
            if hi == '\\' and j < n:
                hi = pattern[j]
                j += 1
            if c <= hi:
                items.append(re.escape(c) + '-' + re.escape(hi))
        else:
            items.append(re.escape(c))

    body = ''.join(items)
    if negate:
        return '[^/' + body + ']', j
    return '(?!/)[' + body + ']', j


def _translate(pattern):
    out = []
    i = 0
    n = len(pattern)
    while i < n:
        c = pattern[i]
        if c == '*':
            if pattern.startswith('**/', i):
                # zero or more whole directories
                out.append('(?:.*/)?')
                i += 3
            elif pattern.startswith('**', i):
                # any characters, including '/'
                out.append('.*')
                i += 2
            else:
                out.append('[^/]*')
                i += 1
        elif c == '?':
            out.append('[^/]')
            i += 1
        elif c == '[':
            parsed = _parse_class(pattern, i)
            if parsed is None:
                out.append(re.escape('['))
                i += 1
            else:
                regex, i = parsed
                out.append(regex)
        elif c == '\\' and i + 1 < n:
            out.append(re.escape(pattern[i + 1]))
            i += 2
        else:
            out.append(re.escape(c))
            i += 1
    return ''.join(out)


def glob_match(pattern, path):
    return re.fullmatch(_translate(pattern), path, re.DOTALL) is not None
