            hi = pattern[j]
            if hi == '\\' and j + 1 < n:
                j += 1
                hi = pattern[j]
            j += 1
            if ord(c) <= ord(hi):
                items.append((c, hi))
        else:
            items.append((c, c))
    else:
        return None

    body = "".join(
        re.escape(lo) if lo == hi else re.escape(lo) + "-" + re.escape(hi)
        for lo, hi in items
    )
    if negate:
        regex = "[^" + body + "/]"
    elif body:
        regex = "(?!/)[" + body + "]"
    else:
        regex = "(?!)"
    return regex, j + 1


def glob_match(pattern, path):
    out = []
    i, n = 0, len(pattern)
    while i < n:
        c = pattern[i]
        if c == '*':
            if pattern.startswith('**', i):
                if pattern.startswith('**/', i) and (i == 0 or pattern[i - 1] == '/'):
                    out.append('(?:.*/)?')
                    i += 3
                else:
                    out.append('.*')
                    i += 2
            else:
                out.append('[^/]*')
                i += 1
        elif c == '?':
            out.append('[^/]')
            i += 1
        elif c == '[':
            r = _class(pattern, i)
            if r is None:
                out.append(re.escape('['))
                i += 1
            else:
                out.append(r[0])
                i = r[1]
        elif c == '\\':
            if i + 1 < n:
                out.append(re.escape(pattern[i + 1]))
                i += 2
            else:
                out.append(re.escape('\\'))
                i += 1
        else:
            out.append(re.escape(c))
            i += 1
    return re.fullmatch(''.join(out), path, re.DOTALL) is not None
