import copy
import re

_SEGMENT = re.compile(r"([^.\[\]]+)((?:\[[0-9]+\])*)\Z")
_INDEX = re.compile(r"\[([0-9]+)\]")


def _parse(path):
    if not isinstance(path, str):
        raise TypeError("path must be a str")
    if not path:
        raise ValueError("empty path")
    steps = []
    for seg in path.split("."):
        m = _SEGMENT.match(seg)
        if m is None:
            raise ValueError(f"malformed path segment {seg!r}")
        steps.append(("key", m.group(1)))
        for im in _INDEX.finditer(m.group(2)):
            steps.append(("idx", int(im.group(1))))
    if steps[0][0] != "key":
        raise ValueError("first step must be a key")
    return steps


def _new_container(kind):
    return {} if kind == "key" else []


def set_path(obj, path, value):
    steps = _parse(path)
    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")

    root = copy.deepcopy(obj)
    node = root
    last = len(steps) - 1

    for i, (kind, key) in enumerate(steps):
        is_last = i == last
        if kind == "key":
            if not isinstance(node, dict):
                raise TypeError(f"key step {key!r} applied to non-dict")
            if is_last:
                node[key] = value
            else:
                if key not in node:
                    node[key] = _new_container(steps[i + 1][0])
                node = node[key]
        else:
            if not isinstance(node, list):
                raise TypeError(f"index step [{key}] applied to non-list")
            if key >= len(node):
                node.extend([None] * (key - len(node)))
                node.append(value if is_last else _new_container(steps[i + 1][0]))
            elif is_last:
                node[key] = value
            if not is_last:
                node = node[key]

    return root
