class Inventory:
    def __init__(self):
        self.lots = {}

    def add(self, sku, qty, expires):
        if qty <= 0:
            raise ValueError("qty must be positive")
        self.lots.setdefault(sku, []).append([expires, qty])

    def _purge(self, sku, today):
        lots = self.lots.get(sku)
        if lots is None:
            return []
        lots[:] = [lot for lot in lots if today <= lot[0] and lot[1] > 0]
        return lots

    def take(self, sku, qty, today):
        if qty <= 0:
            raise ValueError("qty must be positive")
        lots = self._purge(sku, today)
        if sum(lot[1] for lot in lots) < qty:
            raise ValueError("insufficient")
        taken = []
        # sorted() is stable: equal expiry keeps insertion order
        for lot in sorted(lots, key=lambda l: l[0]):
            if qty == 0:
                break
            n = min(qty, lot[1])
            lot[1] -= n
            qty -= n
            taken.append((lot[0], n))
        lots[:] = [lot for lot in lots if lot[1] > 0]
        return taken

    def stock(self, sku, today):
        return sum(lot[1] for lot in self._purge(sku, today))
