import copy
import re

_HEAD_RE = re.compile(r"[^.\[\]]+")
_KEY_RE = re.compile(r"\.([^.\[\]]+)")
_IDX_RE = re.compile(r"\[([0-9]+)\]")


def _parse(path):
    """Split a path into str (key) and int (index) steps. First step is always a key."""
    m = _HEAD_RE.match(path) if isinstance(path, str) else None
    if not m:
        raise ValueError(f"malformed path: {path!r}")
    steps = [m.group()]
    pos = m.end()
    while pos < len(path):
        km = _KEY_RE.match(path, pos)
        if km:
            steps.append(km.group(1))
            pos = km.end()
            continue
        im = _IDX_RE.match(path, pos)
        if im:
            steps.append(int(im.group(1)))
            pos = im.end()
            continue
        raise ValueError(f"malformed path: {path!r}")
    return steps


def _empty_for(next_step):
    return [] if isinstance(next_step, int) else {}


def set_path(obj, path, value):
    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")
    steps = _parse(path)
    root = copy.deepcopy(obj)  # result shares no mutable parts with obj
    node = root
    for i, step in enumerate(steps):
        last = i == len(steps) - 1
        nxt = None if last else steps[i + 1]
        if isinstance(step, str):
            if not isinstance(node, dict):
                raise TypeError(f"key step {step!r} applied to non-dict")
            if last:
                node[step] = value
            else:
                if step not in node:
                    node[step] = _empty_for(nxt)
                node = node[step]
        else:
            if not isinstance(node, list):
                raise TypeError(f"index step [{step}] applied to non-list")
            if step >= len(node):
                node.extend([None] * (step - len(node)))
                node.append(value if last else _empty_for(nxt))
                if not last:
                    node = node[step]
            elif last:
                node[step] = value
            else:
                node = node[step]
    return root


if __name__ == "__main__":
    d = {"a": {"b": [{"c": 1}]}}
    r = set_path(d, "a.b[0].c", 2)
    assert r["a"]["b"][0]["c"] == 2 and d["a"]["b"][0]["c"] == 1  # no mutation
    assert set_path({}, "items[2]", 5) == {"items": [None, None, 5]}  # padding
    assert set_path({}, "a[1]", 3) == {"a": [None, 3]}  # missing list created
    assert set_path({"l": [1]}, "l[1]", 2) == {"l": [1, 2]}  # append
