import copy


def _parse(path):
    if not isinstance(path, str) or path == "":
        raise ValueError("empty path")
    steps = []
    for seg in path.split("."):
        end = seg.find("[")
        name = seg if end == -1 else seg[:end]
        if name == "" or "]" in name:
            raise ValueError(f"malformed path segment: {seg!r}")
        steps.append(("key", name))
        rest = seg[len(name):]
        while rest:
            if not rest.startswith("["):
                raise ValueError(f"malformed path segment: {seg!r}")
            close = rest.find("]")
            if close == -1:
                raise ValueError(f"malformed path segment: {seg!r}")
            num = rest[1:close]
            if not (num.isascii() and num.isdigit()):
                raise ValueError(f"malformed index in path: {seg!r}")
            steps.append(("idx", int(num)))
            rest = rest[close + 1:]
    return steps


def _new_container(kind):
    return {} if kind == "key" else []


def _check_type(child, kind):
    if kind == "key" and not isinstance(child, dict):
        raise TypeError("expected dict for key step")
    if kind == "idx" and not isinstance(child, list):
        raise TypeError("expected list for index step")


def set_path(obj, path, value):
    steps = _parse(path)
    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")
    result = copy.deepcopy(obj)
    node = result
    last_i = len(steps) - 1
    for i, (kind, key) in enumerate(steps):
        if i == last_i:
            if kind == "key":
                node[key] = value
            else:
                if key >= len(node):
                    node.extend([None] * (key - len(node)))
                    node.append(value)
                else:
                    node[key] = value
            break
        nxt = steps[i + 1][0]
        if kind == "key":
            if key not in node:
                node[key] = _new_container(nxt)
            child = node[key]
            _check_type(child, nxt)
            node = child
        else:
            if key >= len(node):
                node.extend([None] * (key - len(node)))
                node.append(_new_container(nxt))
            child = node[key]
            _check_type(child, nxt)
            node = child
    return result
